import json, html
from pathlib import Path

calc=json.loads(Path('/app/output/_calc.json').read_text())
S=calc['summary']

def fmt(x,n=2): return f"{x:.{n}f}"

dec_kpis=''.join([f"<li><strong>{html.escape(k)}</strong>: {v:+.2f}%</li>" for k,v in S['kpi_decade_changes']])

top_rows=''.join([f"<tr><td>{i+1}</td><td>{html.escape(r['country'])}</td><td>{r['homicide_rate']:.2f}</td></tr>" for i,r in enumerate(calc['top10'])])
bot_rows=''.join([f"<tr><td>{i+1}</td><td>{html.escape(r['country'])}</td><td>{r['homicide_rate']:.2f}</td></tr>" for i,r in enumerate(calc['bot10'])])
inc_rows=''.join([f"<tr><td>{html.escape(r['country'])}</td><td>{r['first_year']}</td><td>{r['last_year']}</td><td>{r['pct_change']:+.1f}%</td></tr>" for r in calc['inc']])
dec_rows=''.join([f"<tr><td>{html.escape(r['country'])}</td><td>{r['first_year']}</td><td>{r['last_year']}</td><td>{r['pct_change']:+.1f}%</td></tr>" for r in calc['dec']])

html_doc=f'''<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1" />
<title>Global Intentional Homicide Trends (1990–2023)</title>
<script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script>
<style>
body{{font-family:Arial,sans-serif;margin:24px;background:#f7f9fc;color:#1f2937}}h1,h2{{color:#0f172a}}
.grid{{display:grid;grid-template-columns:repeat(5,minmax(170px,1fr));gap:12px}}.card{{background:#fff;border:1px solid #dbe3ef;border-radius:10px;padding:12px}}
.k{{font-size:12px;color:#475569}}.v{{font-size:24px;font-weight:700;color:#0b3a75}}.s{{font-size:12px;color:#64748b}}
.panel{{background:#fff;border:1px solid #dbe3ef;border-radius:10px;padding:14px;margin:14px 0}}
.two{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}table{{width:100%;border-collapse:collapse}}th,td{{border-bottom:1px solid #e5e7eb;padding:6px 8px;text-align:left}}th{{background:#f8fafc}}
.small{{font-size:13px;color:#334155;line-height:1.45}}
</style></head><body>
<h1>Global Intentional Homicide Trends: A Multi-Dimensional Analysis (1990–2023)</h1>
<p class="small"><strong>Purpose:</strong> Assess whether the world is becoming safer from intentional homicide, identify who remains at highest risk, and support evidence-based prevention and resource allocation decisions using UNODC-derived data in <code>/app/benchmark/data.csv</code>.</p>

<div class="panel"><h2>Executive KPI Snapshot ({S['latest_year']})</h2>
<div class="grid">
<div class="card"><div class="k">Global Median Homicide Rate</div><div class="v">{S['kpi_global_median_latest']:.2f}</div><div class="s">per 100,000</div></div>
<div class="card"><div class="k">Male-to-Female Rate Ratio</div><div class="v">{S['kpi_mf_ratio_latest']:.2f}×</div><div class="s">global matched-country mean ratio ({S['kpi_mf_ratio_year']})</div></div>
<div class="card"><div class="k">Highest National Rate</div><div class="v">{S['kpi_highest_country_latest']['rate']:.2f}</div><div class="s">{html.escape(S['kpi_highest_country_latest']['country'])}</div></div>
<div class="card"><div class="k">Reporting Coverage Rate</div><div class="v">{S['kpi_coverage_latest']*100:.1f}%</div><div class="s">{S['reporting_latest']} of {S['all_countries_n']} countries/territories</div></div>
<div class="card"><div class="k">Highest Age-Group Rate (global mean)</div><div class="v">{S['highest_age_latest']['homicide_rate']:.2f}</div><div class="s">Age {S['highest_age_latest']['age_group']} ({S['latest_age_year']})</div></div>
</div>
<p class="small"><strong>Decade-over-decade change in global average homicide rate:</strong></p><ul class="small">{dec_kpis}</ul></div>

<div class="panel"><h2>1) Global Homicide Rate Overview</h2><div id="chart_global"></div><p class="small">The global trajectory is mixed. Cross-country mean homicide rates rose from the 1990s to 2000s, declined through the 2010s, then ticked up in the early 2020s (partial decade). The median remains far below the mean in many years, indicating persistent high-rate outliers.</p></div>

<div class="panel"><h2>2) Regional & Country-Level Comparison</h2><div id="chart_topbot"></div><div class="two"><div><h3>Top 10 countries/territories by homicide rate ({S['latest_year']})</h3><table><tr><th>#</th><th>Country</th><th>Rate</th></tr>{top_rows}</table></div><div><h3>Bottom 10 countries/territories ({S['latest_year']})</h3><table><tr><th>#</th><th>Country</th><th>Rate</th></tr>{bot_rows}</table></div></div></div>

<div class="panel"><h2>3) Gender Disparity in Homicide Victimization</h2><div id="chart_ratio"></div><p class="small">Gender disparity is structurally large: male victimization rates substantially exceed female rates across virtually all years with matched reporting. In the latest year, the global male-to-female rate ratio is <strong>{S['kpi_mf_ratio_latest']:.2f}x</strong>.</p></div>

<div class="panel"><h2>4) Age Group Analysis</h2><div id="chart_age"></div><p class="small">Across reported country-year-age observations, young adult groups (especially 20s) tend to show the highest homicide risk. This aligns with the need for targeted youth and young-adult violence prevention strategies.</p></div>

<div class="panel"><h2>5) Notable Country-Level Trends & Outliers</h2><div id="chart_outliers"></div><div class="two"><div><h3>Largest increases (first vs last observed, countries with ≥10 observations)</h3><table><tr><th>Country</th><th>First</th><th>Last</th><th>% Change</th></tr>{inc_rows}</table></div><div><h3>Largest decreases (first vs last observed, countries with ≥10 observations)</h3><table><tr><th>Country</th><th>First</th><th>Last</th><th>% Change</th></tr>{dec_rows}</table></div></div></div>

<div class="panel"><h2>6) Data Limitations & Policy Recommendations</h2>
<ul class="small">
<li><strong>Unbalanced panel:</strong> country coverage varies materially by year; trend interpretation should account for changing reporter composition.</li>
<li><strong>Coverage gap:</strong> latest-year reporting is {S['kpi_coverage_latest']*100:.1f}% of all observed countries/territories in this dataset.</li>
<li><strong>No imputation:</strong> missing years are absent rows, not estimated values; all calculations use available observations only.</li>
<li><strong>Comparability caveat:</strong> UK observations represent England and Wales in this source framing.</li>
</ul>
<p class="small"><strong>Actionable implications:</strong> prioritize prevention and policing resources toward high-rate outlier contexts; sustain male-focused violence interruption while preserving protection responses for women and girls; invest in standardized, sex- and age-disaggregated reporting systems; and benchmark progress with robust distributional metrics (median, percentile spread), not mean alone.</p>
</div>

<script>
const calc={json.dumps(calc)};
const ys=calc.ys;
Plotly.newPlot('chart_global',[
{{x:ys.map(d=>d.year),y:ys.map(d=>d.mean_rate),name:'Global Mean',mode:'lines',line:{{color:'#1d4ed8',width:3}}}},
{{x:ys.map(d=>d.year),y:ys.map(d=>d.median_rate),name:'Global Median',mode:'lines',line:{{color:'#0f766e',width:3}}}},
{{x:ys.map(d=>d.year),y:ys.map(d=>d.reporting_countries),name:'Reporting Countries',yaxis:'y2',mode:'lines',line:{{color:'#7c3aed',dash:'dot'}}}}
],{{margin:{{t:20}},xaxis:{{title:'Year'}},yaxis:{{title:'Homicide rate per 100,000'}},yaxis2:{{title:'Reporting countries',overlaying:'y',side:'right'}},legend:{{orientation:'h'}}}},{{displayModeBar:false,responsive:true}});

Plotly.newPlot('chart_topbot',[
{{x:calc.top10.map(d=>d.country),y:calc.top10.map(d=>d.homicide_rate),type:'bar',name:'Top 10',marker:{{color:'#b91c1c'}}}},
{{x:calc.bot10.map(d=>d.country),y:calc.bot10.map(d=>d.homicide_rate),type:'bar',name:'Bottom 10',marker:{{color:'#0369a1'}}}}
],{{barmode:'group',margin:{{t:20,b:120}},xaxis:{{tickangle:-45}},yaxis:{{title:'Rate per 100,000'}}}},{{displayModeBar:false,responsive:true}});

Plotly.newPlot('chart_ratio',[{{x:calc.ratio_year.map(d=>d.year),y:calc.ratio_year.map(d=>d.ratio),mode:'lines',line:{{color:'#be185d',width:3}},name:'Male/Female ratio'}}],{{margin:{{t:20}},xaxis:{{title:'Year'}},yaxis:{{title:'Ratio (x)'}}}},{{displayModeBar:false,responsive:true}});

const ageGroups=[...new Set(calc.age_year.map(d=>d.age_group))].sort();
const latestAge=Math.max(...calc.age_year.map(d=>d.year));
const ageLatest=calc.age_year.filter(d=>d.year===latestAge).sort((a,b)=>b.homicide_rate-a.homicide_rate);
Plotly.newPlot('chart_age',[{{x:ageLatest.map(d=>d.age_group),y:ageLatest.map(d=>d.homicide_rate),type:'bar',marker:{{color:'#0f766e'}}}}],{{margin:{{t:20}},xaxis:{{title:'Age group'}},yaxis:{{title:'Global mean homicide rate'}}}},{{displayModeBar:false,responsive:true}});

const inc=calc.inc.slice().reverse();
const dec=calc.dec.slice();
Plotly.newPlot('chart_outliers',[
{{x:dec.map(d=>d.pct_change),y:dec.map(d=>d.country),type:'bar',orientation:'h',name:'Largest decreases',marker:{{color:'#047857'}}}},
{{x:inc.map(d=>d.pct_change),y:inc.map(d=>d.country),type:'bar',orientation:'h',name:'Largest increases',marker:{{color:'#dc2626'}}}}
],{{barmode:'overlay',margin:{{t:20,l:160}},xaxis:{{title:'% change (first vs last observed)'}}}},{{displayModeBar:false,responsive:true}});
</script>
</body></html>'''

Path('/app/output/final_report.html').write_text(html_doc,encoding='utf-8')
print('written /app/output/final_report.html')
PY

